/**
 * Research traceability matrix — generator + validator.
 *
 * Usage:
 *   node scripts/validate-traceability-matrix.mjs           # validate (CI-style)
 *   node scripts/validate-traceability-matrix.mjs --write   # regenerate mechanical sections
 *
 * The matrix file is docs/research/research-traceability-matrix.json.
 * MECHANICAL sections (regenerated by --write, byte-compared by validate):
 *   - events                       (per-event registration/emission/scoring/test facts)
 *   - meta.derived_counts
 *   - findings.scoring_terms_without_tested_sources
 *   - findings.events_lacking_direct_test_coverage
 * HAND-AUTHORED sections (preserved by --write, referentially validated):
 *   - items (Q01–Q33), annotations, summary_variable_sources,
 *     findings.* (all other keys), sources, meta.* (other keys)
 *
 * Scientific rule: this script never invents mappings. All mechanical facts are
 * extracted verbatim from src/ and e2e/; disagreements between the checked-in
 * matrix and the extraction fail validation instead of being auto-resolved.
 */
/* eslint-disable no-console -- CLI validation tool; console output is the interface. */
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const MATRIX_PATH = join(
  ROOT,
  'docs/research/research-traceability-matrix.json',
);

// ————————————————————————————————————————————————————————————————————————
// Extraction helpers
// ————————————————————————————————————————————————————————————————————————

function stripComments(text) {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/^\s*\/\/.*$/gm, '')
    .replace(/(\s)\/\/[^\n]*$/gm, '$1');
}

function walk(dir, exts) {
  const out = [];
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) out.push(...walk(p, exts));
    else if (exts.some((e) => name.endsWith(e))) out.push(p);
  }
  return out;
}

function rel(p) {
  return p.slice(ROOT.length + 1).replace(/\\/g, '/');
}

/** Parse CANONICAL_EVENT_CONTEXT entries: study_item_ids / construct_id / success. */
function parseRegistrations() {
  const src = readFileSync(
    join(ROOT, 'src/world/CanonicalEventContext.ts'),
    'utf8',
  );
  const start = src.indexOf('CANONICAL_EVENT_CONTEXT');
  const body = src.slice(start, src.indexOf('\n};', start));
  const entries = {};
  const entryRe = /^ {2}([a-z0-9_]+): \{\n([\s\S]*?)^ {2}\},?$/gm;
  const inlineRe = /^ {2}([a-z0-9_]+): \{ ([^\n]*?) \},?$/gm;
  for (const m of body.matchAll(entryRe)) entries[m[1]] = parseEntryBody(m[2]);
  for (const m of body.matchAll(inlineRe)) entries[m[1]] = parseEntryBody(m[2]);
  return entries;
}

function parseEntryBody(text) {
  const clean = stripComments(text);
  const ids = clean.match(/study_item_ids:\s*\[([^\]]*)\]/);
  const construct = clean.match(/construct_id:\s*'([a-z_]+)'/);
  const success = clean.match(/success:\s*(true|false|null)/);
  return {
    study_item_ids: ids
      ? (ids[1].match(/'[^']+'/g)?.map((s) => s.slice(1, -1)) ?? [])
      : null,
    construct_id: construct ? construct[1] : null,
    success: success ? success[1] : 'unset',
  };
}

/** Map: quoted snake_case literal -> sorted file list, comments stripped. */
function extractLiteralLocations(files) {
  const locations = {};
  for (const f of files) {
    const text = stripComments(readFileSync(f, 'utf8'));
    for (const m of text.matchAll(/'([a-z0-9]+(?:_[a-z0-9]+)+)'/g)) {
      (locations[m[1]] ??= new Set()).add(rel(f));
    }
  }
  return locations;
}

function parseScoring() {
  const src = readFileSync(join(ROOT, 'src/systems/ScoringManager.ts'), 'utf8');
  const counting = src.slice(src.indexOf('function countEventTypes'));
  const inputs = [
    ...new Set(
      [...counting.matchAll(/countEvents\(\s*events,\s*'([a-z0-9_]+)'/g)].map(
        (m) => m[1],
      ),
    ),
  ].sort();
  const iface = src.slice(
    src.indexOf('export interface GameSummaryVariables'),
    src.indexOf('\n}', src.indexOf('export interface GameSummaryVariables')),
  );
  const summaryFields = [...iface.matchAll(/^ {2}([a-z0-9_]+):/gm)].map(
    (m) => m[1],
  );
  return { inputs, summaryFields };
}

// ————————————————————————————————————————————————————————————————————————
// Event universe + room derivation
// ————————————————————————————————————————————————————————————————————————

// Canonical/legacy events that are neither registered, scoring inputs, nor
// necessarily emitted, but belong in the matrix (documented in
// docs/research/event-schema.md §4 tables or the D2–D8 decision brief).
const SEED_EVENTS = [
  'task_started',
  'hazard_issue_created',
  'hazard_issue_resolved',
  'final_hazard_issue',
  'engineer_supervision_skipped',
  'final_quality_score_computed',
  'final_summary_previewed',
  'qualtrics_return_previewed',
  'inventory_sequence_completed',
  'readiness_verified',
  'side_repair_abandoned',
  // Emitted-but-unregistered events (room entry / additive canonical /
  // legacy prototype names) — the extraction confirms code references.
  'archive_room_entered',
  'archive_terminal_opened',
  'archive_code_entered',
  'archive_feedback_shown',
  'archive_log_compared',
  'archive_attempt',
  'repair_room_entered',
  'repair_panel_opened',
  'repair_sequence_submitted',
  'repair_manual_opened',
  'engineer_hub_entered',
  'engineer_supervision_assigned',
  'engineer_supervision_declined',
  'inventory_room_entered',
  'inventory_prep_opened',
  'inventory_required_tools_packed',
  'inventory_required_item_missed',
  'missing_item',
  'hazard_room_entered',
  'side_repair_opened',
  'side_repair_discovered',
  'side_repair_deferred',
  'interruption_corridor_entered',
  'interruption_opened',
  'interruption_previous_task_abandoned',
  'interruption_single_task_focus',
  'final_core_entered',
  'final_core_opened',
  'session_start',
  'scene_start',
];

const ROOM_OVERRIDES = {
  accepted_duty_unresolved: ['engineer_hub', 'final_core_room'],
  engineer_supervision_completed: ['final_core_room'],
  final_unresolved_due_to_nonreturn: ['final_core_room'],
  manual_page_reviewed: ['systems_repair_room'],
  task_started: [
    'archive_room',
    'systems_repair_room',
    'interruption_corridor',
  ],
  objective_completed: ['archive_room', 'systems_repair_room'],
  final_hazard_issue: ['final_core_room'],
  issue_resolution_attempted: ['final_core_room'],
  unresolved_issue_reviewed: ['final_core_room'],
  final_bonus_unlocked: ['optional_side_repair_bay'],
  final_quality_score_computed: ['scoring_layer'],
  final_summary_previewed: ['scoring_layer'],
  qualtrics_return_previewed: ['scoring_layer'],
  session_start: ['system'],
  scene_start: ['system'],
  missing_item: ['inventory_prep_room'],
  readiness_verified: ['inventory_prep_room'],
};

const ROOM_PREFIXES = [
  ['archive_', 'archive_room'],
  ['repair_', 'systems_repair_room'],
  ['engineer_', 'engineer_hub'],
  ['inventory_', 'inventory_prep_room'],
  ['workspace_', 'inventory_prep_room'],
  ['cleanup_', 'inventory_prep_room'],
  ['correct_tool_', 'inventory_prep_room'],
  ['wrong_tool_', 'inventory_prep_room'],
  ['prepared_tool_', 'inventory_prep_room'],
  ['hazard_', 'hazard_control_room'],
  ['side_repair_', 'optional_side_repair_bay'],
  ['stabiliser_', 'optional_side_repair_bay'],
  ['interruption_', 'interruption_corridor'],
  ['switched_task', 'interruption_corridor'],
  ['returned_to_original_task', 'interruption_corridor'],
  ['task_avoidance', 'interruption_corridor'],
  ['objective_active', 'interruption_corridor'],
  ['competing_task_viewed', 'interruption_corridor'],
  ['new_goal_offered', 'interruption_corridor'],
  ['goal_switch_accepted', 'interruption_corridor'],
  ['prior_goal_', 'interruption_corridor'],
  ['return_to_unfinished_task', 'interruption_corridor'],
  ['task_completed_after_interruption', 'interruption_corridor'],
  ['excessive_idle_after_instruction', 'interruption_corridor'],
  ['final_core_', 'final_core_room'],
  ['dock_', 'dock_arrival'],
  ['tutorial_', 'dock_arrival'],
  ['first_movement', 'dock_arrival'],
  ['first_interaction', 'dock_arrival'],
  ['movement_instruction_shown', 'dock_arrival'],
  ['control_error_count', 'dock_arrival'],
  ['baseline_idle_seconds', 'dock_arrival'],
  ['station_hub_', 'station_hub'],
];

function deriveRooms(event) {
  if (ROOM_OVERRIDES[event]) return ROOM_OVERRIDES[event];
  for (const [prefix, room] of ROOM_PREFIXES) {
    if (event.startsWith(prefix)) return [room];
  }
  return ['unassigned'];
}

// ————————————————————————————————————————————————————————————————————————
// Mechanical derivation
// ————————————————————————————————————————————————————————————————————————

function derive() {
  const registrations = parseRegistrations();
  const scoring = parseScoring();
  const srcFiles = walk(join(ROOT, 'src'), ['.ts', '.tsx']).filter(
    (f) => !f.includes('CanonicalEventContext'),
  );
  const codeRefs = extractLiteralLocations(srcFiles);
  const specRefs = extractLiteralLocations(walk(join(ROOT, 'e2e'), ['.ts']));

  const universe = [
    ...new Set([
      ...Object.keys(registrations),
      ...scoring.inputs,
      ...SEED_EVENTS,
    ]),
  ].sort();

  const events = {};
  for (const name of universe) {
    const reg = registrations[name];
    events[name] = {
      rooms: deriveRooms(name),
      registered: Boolean(reg),
      study_item_ids: reg ? reg.study_item_ids : null,
      construct_id: reg ? reg.construct_id : null,
      success: reg ? reg.success : 'unset',
      scoring_input: scoring.inputs.includes(name),
      code_references: [...(codeRefs[name] ?? [])].sort(),
      spec_references: [...(specRefs[name] ?? [])].sort(),
    };
  }

  const untestedScoringInputs = scoring.inputs.filter(
    (e) => events[e].spec_references.length === 0,
  );
  const untestedEmitted = universe.filter(
    (e) =>
      events[e].code_references.length > 0 &&
      events[e].spec_references.length === 0,
  );

  return {
    events,
    scoring,
    derived_counts: {
      events_total: universe.length,
      registered: Object.keys(registrations).length,
      scoring_inputs: scoring.inputs.length,
      summary_variables: scoring.summaryFields.length,
      with_code_references: universe.filter(
        (e) => events[e].code_references.length > 0,
      ).length,
      with_spec_references: universe.filter(
        (e) => events[e].spec_references.length > 0,
      ).length,
    },
    findings_mechanical: {
      scoring_terms_without_tested_sources: untestedScoringInputs,
      events_lacking_direct_test_coverage: untestedEmitted,
    },
  };
}

// ————————————————————————————————————————————————————————————————————————
// Modes
// ————————————————————————————————————————————————————————————————————————

const ALLOWED_DECISIONS = [
  'D2',
  'D3',
  'D4',
  'D5',
  'D6',
  'D7',
  'D8',
  'UD-HAZARD-CONSEQUENCE',
];
const Q_IDS = Array.from(
  { length: 33 },
  (_, i) => `Q${String(i + 1).padStart(2, '0')}`,
);

function loadMatrix() {
  return JSON.parse(readFileSync(MATRIX_PATH, 'utf8'));
}

function write() {
  let matrix = {};
  try {
    matrix = loadMatrix();
  } catch {
    // First generation: start from an empty skeleton.
  }
  const d = derive();
  matrix.meta = { ...(matrix.meta ?? {}), derived_counts: d.derived_counts };
  matrix.events = d.events;
  matrix.findings = {
    ...(matrix.findings ?? {}),
    ...d.findings_mechanical,
  };
  matrix.items ??= [];
  matrix.annotations ??= {};
  matrix.summary_variable_sources ??= {};
  matrix.sources ??= {};
  writeFileSync(MATRIX_PATH, JSON.stringify(matrix, null, 2) + '\n');
  console.log(
    `wrote ${rel(MATRIX_PATH)} (${Object.keys(d.events).length} events)`,
  );
}

function validate() {
  const errors = [];
  const matrix = loadMatrix();
  const d = derive();

  // 1. Mechanical sections must match the fresh derivation exactly.
  if (JSON.stringify(matrix.events) !== JSON.stringify(d.events)) {
    const names = new Set([
      ...Object.keys(matrix.events ?? {}),
      ...Object.keys(d.events),
    ]);
    for (const n of names) {
      const a = JSON.stringify(matrix.events?.[n]);
      const b = JSON.stringify(d.events[n]);
      if (a !== b)
        errors.push(`events.${n} stale:\n  matrix:  ${a}\n  derived: ${b}`);
    }
  }
  if (
    JSON.stringify(matrix.meta?.derived_counts) !==
    JSON.stringify(d.derived_counts)
  ) {
    errors.push('meta.derived_counts stale — run --write');
  }
  for (const key of Object.keys(d.findings_mechanical)) {
    if (
      JSON.stringify(matrix.findings?.[key]) !==
      JSON.stringify(d.findings_mechanical[key])
    ) {
      errors.push(`findings.${key} stale — run --write`);
    }
  }

  // 2. Items: exactly Q01–Q33, each event referenced must exist.
  const itemIds = (matrix.items ?? []).map((i) => i.id);
  if (JSON.stringify(itemIds) !== JSON.stringify(Q_IDS)) {
    errors.push(
      `items must be exactly Q01–Q33 in order; got ${itemIds.length} ids`,
    );
  }
  for (const item of matrix.items ?? []) {
    for (const ev of item.events ?? []) {
      if (!matrix.events[ev])
        errors.push(`${item.id} references unknown event '${ev}'`);
    }
    // Registered study_item_ids must agree with the item linkage in both
    // directions for registered events — except divergences between the two
    // authoritative sources that are explicitly catalogued (never silently
    // resolved) in known_listing_divergences.
    for (const ev of item.events ?? []) {
      const rec = matrix.events[ev];
      const known = (matrix.known_listing_divergences ?? []).some(
        (k) => k.item === item.id && k.event === ev,
      );
      if (
        rec?.registered &&
        rec.study_item_ids &&
        !rec.study_item_ids.includes(item.id) &&
        !known
      ) {
        errors.push(
          `${item.id} lists '${ev}' but its registration maps to [${rec.study_item_ids}]`,
        );
      }
    }
  }
  // Reverse direction: every registered non-empty study_item_id appears on that item row.
  for (const [ev, rec] of Object.entries(matrix.events)) {
    for (const q of rec.study_item_ids ?? []) {
      const item = (matrix.items ?? []).find((i) => i.id === q);
      if (item && !(item.events ?? []).includes(ev)) {
        errors.push(
          `registration maps '${ev}' to ${q} but ${q}'s item row omits it`,
        );
      }
    }
  }

  for (const k of matrix.known_listing_divergences ?? []) {
    if (!Q_IDS.includes(k.item) || !matrix.events[k.event]) {
      errors.push(
        `known_listing_divergences entry references unknown item/event: ${k.item}/${k.event}`,
      );
    }
  }

  // 3. Annotations reference real events; decisions from the allowed registry.
  for (const [ev, ann] of Object.entries(matrix.annotations ?? {})) {
    if (!matrix.events[ev]) errors.push(`annotation for unknown event '${ev}'`);
    for (const dec of ann.blocking_decisions ?? []) {
      if (!ALLOWED_DECISIONS.includes(dec)) {
        errors.push(`annotation '${ev}' names unknown decision '${dec}'`);
      }
    }
  }

  // 4. Summary variable sources: keys must be exactly GameSummaryVariables
  //    fields; every referenced event must be a ScoringManager input.
  const svKeys = Object.keys(matrix.summary_variable_sources ?? {}).sort();
  const expected = [...d.scoring.summaryFields].sort();
  if (JSON.stringify(svKeys) !== JSON.stringify(expected)) {
    const missing = expected.filter((k) => !svKeys.includes(k));
    const extra = svKeys.filter((k) => !expected.includes(k));
    errors.push(
      `summary_variable_sources keys != GameSummaryVariables fields` +
        (missing.length ? `; missing: ${missing}` : '') +
        (extra.length ? `; extra: ${extra}` : ''),
    );
  }
  for (const [field, src] of Object.entries(
    matrix.summary_variable_sources ?? {},
  )) {
    for (const ev of src.events ?? []) {
      if (!matrix.events[ev]) {
        errors.push(
          `summary variable '${field}' references unknown event '${ev}'`,
        );
      } else if (!matrix.events[ev].scoring_input) {
        errors.push(
          `summary variable '${field}' references '${ev}' which is not a ScoringManager input`,
        );
      }
    }
  }

  // 5. Findings hand lists: referenced ids must exist.
  for (const q of matrix.findings?.items_without_full_operationalisation ??
    []) {
    if (!Q_IDS.includes(q.id))
      errors.push(`finding references unknown item '${q.id}'`);
  }
  for (const group of [
    'events_without_approved_mappings',
    'ambiguous_behavioural_meanings',
  ]) {
    for (const entry of matrix.findings?.[group] ?? []) {
      if (entry.event && !matrix.events[entry.event]) {
        errors.push(
          `findings.${group} references unknown event '${entry.event}'`,
        );
      }
    }
  }

  if (errors.length > 0) {
    console.error(`TRACEABILITY MATRIX INVALID (${errors.length} error(s)):`);
    for (const e of errors) console.error(' - ' + e);
    process.exit(1);
  }
  console.log(
    `traceability matrix OK: ${Object.keys(matrix.events).length} events, ` +
      `${matrix.items.length} items, ` +
      `${Object.keys(matrix.summary_variable_sources).length} summary variables`,
  );
}

if (process.argv.includes('--write')) write();
else validate();
